-- Original short practice materials, with answer explanations. Listening uses
-- synthetic narration of original scripts; these are not official IELTS papers.
DO $seed$
DECLARE source jsonb; question jsonb; choice text; answer text;
 eid uuid; vid uuid; sid uuid; qid uuid; pos integer; opt integer; draft jsonb;
BEGIN
 FOR source IN SELECT value FROM jsonb_array_elements('[{"title":"A Library of Things","skill":"reading","passage":"On a former shop floor in Northbridge, residents can borrow objects rather than books. The Library of Things opened in March after a six-month trial at the community centre. Its collection includes sewing machines, carpet cleaners and camping equipment. Members pay twelve pounds a year and a small fee each time they borrow an item. Volunteers explain how unfamiliar equipment works before it leaves the building.\n\nThe organisers initially expected camping equipment to attract the most interest. In fact, carpet cleaners accounted for almost half of all loans during the first three months. This surprised the team, which then bought two additional cleaners. No comparable increase was made to the camping collection.\n\nEvery returned item is checked. Small repairs are carried out by volunteers, while electrical faults are referred to a qualified technician. An item is removed from the catalogue until it is safe to lend again. The organisers say that shared access can reduce unnecessary purchases, although they have not yet measured the scheme''s environmental impact.","questions":[{"type":"multiple_choice","prompt":"Which item was borrowed most often?","answers":["Carpet cleaners"],"options":["Camping equipment","Carpet cleaners","Sewing machines"],"explanation":"Carpet cleaners made up almost half of all loans in the first three months."},{"type":"short_answer","prompt":"How long did the trial last? Use no more than THREE words.","answers":["six months"],"options":[],"explanation":"The opening paragraph describes a six-month trial; the duration is six months."},{"type":"true_false_not_given","prompt":"The library has measured its environmental impact.","answers":["False"],"options":["True","False","Not Given"],"explanation":"The last sentence explicitly says the organisers have not yet measured it."},{"type":"short_answer","prompt":"Who handles electrical faults? Use no more than THREE words.","answers":["a qualified technician"],"options":[],"explanation":"Electrical faults are referred to a qualified technician rather than repaired by volunteers."},{"type":"true_false_not_given","prompt":"Members must live within two kilometres of the library.","answers":["Not Given"],"options":["True","False","Not Given"],"explanation":"No residence-distance requirement appears in the passage."}],"slug":"library-of-things"},{"title":"Cooling the Schoolyard","skill":"reading","passage":"A primary school replaced part of its asphalt playground with trees and a shallow rain garden. The project began after teachers noticed that pupils avoided the southern corner on hot afternoons. Before changing the surface, a geography class recorded temperatures at five locations for two weeks. The hottest readings came from an unshaded area beside a brick wall.\n\nThe school planted young trees in November so their roots could develop before summer. Because the trees initially provided little shade, temporary fabric canopies were installed. The rain garden was designed to hold water briefly after storms and allow it to soak into the ground. It was not intended to remain a pond.\n\nOne year later, measurements taken on sunny afternoons showed lower surface temperatures beneath the canopies than on the remaining asphalt. However, the school did not claim that the trees alone caused the difference: the new planting, canopies and surface materials had all changed together. Teachers now use the site for lessons on insects and water movement. Pupils help remove litter, but adults are responsible for pruning.","questions":[{"type":"short_answer","prompt":"For how long were temperatures recorded before the work? Use no more than TWO words.","answers":["two weeks"],"options":[],"explanation":"The geography class measured five locations for two weeks before the changes."},{"type":"multiple_choice","prompt":"Why were temporary canopies installed?","answers":["The young trees offered little shade"],"options":["The trees needed less water","The young trees offered little shade","The brick wall was removed"],"explanation":"The passage links the canopies to the young trees initially providing little shade."},{"type":"true_false_not_given","prompt":"The rain garden was designed as a permanent pond.","answers":["False"],"options":["True","False","Not Given"],"explanation":"It holds water briefly; the text explicitly says it was not intended to remain a pond."},{"type":"true_false_not_given","prompt":"The school proved that trees alone reduced the temperatures.","answers":["False"],"options":["True","False","Not Given"],"explanation":"Several things changed together, so the school did not attribute the result to trees alone."},{"type":"short_answer","prompt":"Who is responsible for pruning? Use ONE word.","answers":["adults"],"options":[],"explanation":"The final sentence assigns pruning to adults, while pupils remove litter."}],"slug":"cooling-schoolyard"},{"title":"Museum Workshop Booking","skill":"listening","passage":"Thank you for calling the Riverside Museum. Our Saturday photography workshop will take place on the fourteenth of November. The morning session was originally advertised for ten o''clock, but it will now start at half past ten because the main gallery opens later that day. Please arrive fifteen minutes before the session begins. The workshop costs eighteen pounds per person, including a printed guide. You do not need a professional camera: a phone camera is fine. Please bring a notebook, however, as we cannot supply one. Meet the tutor at the east entrance, opposite the bicycle racks. Do not wait by the gift shop. The workshop is limited to twelve people, so booking is essential. To reserve a place, give your name and contact number to the reception team.","questions":[{"type":"short_answer","prompt":"What date is the workshop? Write no more than THREE words and/or a number.","answers":["14 November","fourteenth of November","November 14"],"options":[],"explanation":"The announced date is the fourteenth of November."},{"type":"short_answer","prompt":"What is the revised start time?","answers":["10:30","half past ten","10.30"],"options":[],"explanation":"Ten o''clock is the old time; the speaker corrects it to half past ten."},{"type":"short_answer","prompt":"How much does the workshop cost in pounds?","answers":["18","eighteen"],"options":[],"explanation":"The price is eighteen pounds and includes a printed guide."},{"type":"multiple_choice","prompt":"What should participants bring?","answers":["A notebook"],"options":["A professional camera","A printed guide","A notebook"],"explanation":"Phone cameras are acceptable, the guide is included, but participants must bring a notebook."},{"type":"multiple_choice","prompt":"Where should participants meet?","answers":["The east entrance"],"options":["The gift shop","The east entrance","The main gallery"],"explanation":"The speaker explicitly says the east entrance and warns against waiting at the gift shop."}],"slug":"museum-workshop"},{"title":"Community Garden Orientation","skill":"listening","passage":"Welcome to the Elm Street community garden. New members can collect their gate keys from the library desk, not from the garden shed. The library is open until six on weekdays. Our shared work session takes place on the first Sunday of each month, starting at nine in the morning. You may have seen an old notice mentioning Saturday; please ignore that. Bring gardening gloves. Tools are supplied and must be returned to the shed after use. Water is collected in two large tanks behind the greenhouse. During dry weather, please use watering cans rather than the hose. The annual membership fee is twenty-four pounds. Students pay half that amount if they show a valid student card. Finally, please leave the narrow path beside the fence clear because it is our emergency access route.","questions":[{"type":"multiple_choice","prompt":"Where do new members collect gate keys?","answers":["The library desk"],"options":["The garden shed","The greenhouse","The library desk"],"explanation":"The introduction says the library desk, explicitly excluding the garden shed."},{"type":"short_answer","prompt":"On which day of the week is the monthly work session? Use ONE word.","answers":["Sunday"],"options":[],"explanation":"The correct day is Sunday; Saturday appears only on an outdated notice."},{"type":"short_answer","prompt":"What should members bring? Use no more than TWO words.","answers":["gardening gloves","gloves"],"options":[],"explanation":"Tools are supplied, but members are asked to bring gardening gloves."},{"type":"short_answer","prompt":"How much is the annual student fee in pounds?","answers":["12","twelve"],"options":[],"explanation":"The standard annual fee is twenty-four pounds and students pay half: twelve pounds."},{"type":"multiple_choice","prompt":"Why must the path beside the fence stay clear?","answers":["It provides emergency access"],"options":["It is a bicycle parking area","It provides emergency access","It stores watering cans"],"explanation":"The final sentence identifies the path as the emergency access route."}],"slug":"garden-orientation"}]'::jsonb) LOOP
 INSERT INTO exams(slug,created_by) VALUES ('practice-'||(source->>'slug'),'00000000-0000-4000-8000-000000000001') RETURNING id INTO eid;
 INSERT INTO exam_versions(exam_id,version,title,description,skill,purpose,status,duration_seconds,instructions,published_at)
 VALUES(eid,1,source->>'title','Original short practice with explanations.',(source->>'skill')::exam_skill,'practice','published',600,'Practice for accuracy. These materials are not official IELTS papers.',now()) RETURNING id INTO vid;
 INSERT INTO exam_sections(exam_version_id,position,title,instructions,passage,audio_url)
 VALUES(vid,1,source->>'title',CASE WHEN source->>'skill'='listening' THEN 'Listen to the original announcement (synthetic narration), then answer.' ELSE 'Read the passage carefully and follow the word limits.' END,source->>'passage',
 CASE WHEN source->>'skill'='listening' THEN 'https://mock.web.chessinsight.uz/audio/'||(source->>'slug')||'.m4a' ELSE NULL END) RETURNING id INTO sid;
 pos:=0;
 FOR question IN SELECT value FROM jsonb_array_elements(source->'questions') LOOP
 pos:=pos+1;
 INSERT INTO questions(section_id,position,type,prompt,explanation) VALUES(sid,pos,(question->>'type')::question_type,question->>'prompt',question->>'explanation') RETURNING id INTO qid;
 opt:=0;
 FOR choice IN SELECT jsonb_array_elements_text(question->'options') LOOP
 opt:=opt+1;INSERT INTO question_options(question_id,position,label,value) VALUES(qid,opt,chr(64+opt),choice);
 END LOOP;
 opt:=0;
 FOR answer IN SELECT jsonb_array_elements_text(question->'answers') LOOP
 opt:=opt+1;INSERT INTO accepted_answers(question_id,position,value) VALUES(qid,opt,answer);
 END LOOP;
 END LOOP;
 draft:=jsonb_build_object('title',source->>'title','description','Original short practice with explanations.','skill',source->>'skill','purpose','practice','duration_seconds',600,'instructions','Practice for accuracy. These materials are not official IELTS papers.','bands','[]'::jsonb,
 'sections',jsonb_build_array(jsonb_build_object('title',source->>'title','passage',source->>'passage','instructions',CASE WHEN source->>'skill'='listening' THEN 'Original script with synthetic narration.' ELSE 'Read carefully.' END,'audio_url',CASE WHEN source->>'skill'='listening' THEN 'https://mock.web.chessinsight.uz/audio/'||(source->>'slug')||'.m4a' ELSE '' END,'questions',source->'questions')));
 INSERT INTO content_drafts(exam_id,author_id,data) VALUES(eid,'00000000-0000-4000-8000-000000000001',draft);
 END LOOP;
END $seed$;

